inline simulator_callback::simulator_callback(const struct t_cb_data*data)
{
      cb_data = *data;
      if ((data->reason == cbNextSimTime) && data->time) {
	    cb_time = *(data->time);
      } else if (data->reason == cbEndOfSimulation) {
	    cb_time.type = vpiSimTime;
      } else {
	    cb_time.type = vpiSuppressTime;
      }
      cb_data.time = &cb_time;
}

startupExecution.excerpt:
void vpiStartOfSim(void) {
      simulator_callback* cur;

      /*
       * Walk the list of register callbacks, executing them and
       * freeing them when done.
       */
      assert(vpi_mode_flag == VPI_MODE_NONE);
      vpi_mode_flag = VPI_MODE_RWSYNC;

      while (StartOfSimulation) {
	    cur = StartOfSimulation;
	    StartOfSimulation = dynamic_cast<simulator_callback*>(cur->next);
	    if (cur->cb_data.cb_rtn != 0) {
		  (cur->cb_data.cb_rtn)(&cur->cb_data);
	    }
	    delete cur;
      }

      vpi_mode_flag = VPI_MODE_NONE;
}

schedulerOrder.excerpt:
void schedule_simulate(void)
{
      bool run_finals;
      sim_started = false;

      schedule_time = 0;

      if (verbose_flag) {
	    vpi_mcd_printf(1, " ...execute EndOfCompile callbacks\n");
      }

      // Execute end of compile callbacks
      vpiEndOfCompile();

      if (verbose_flag) {
	    vpi_mcd_printf(1, " ...propagate initialization events\n");
      }

	// Execute initialization events.
      while (schedule_init_list) {
	    struct event_s*cur = schedule_init_list->next;
	    if (cur->next == cur) {
		  schedule_init_list = 0;
	    } else {
		  schedule_init_list->next = cur->next;
	    }
	    cur->run_run();
	    delete cur;
      }

      sim_started = true;

      if (verbose_flag) {
	    vpi_mcd_printf(1, " ...execute StartOfSim callbacks\n");
      }

      // Execute start of simulation callbacks
      vpiStartOfSim();

